export const glacierTopic={id:'geography.a.glaciers',title:'Glaciated upland landscapes and processes',discipline:'Physical geography'};
const q=(u,n,prompt,options,answer,why,concept)=>({id:`geo.a.g1.${u}.${n}`,prompt,options,answer,why,concept:'geo.a.glacier.'+concept});
const make=(slug,title,refs,cards,tasks,practice,check,model,cardViews)=>({id:'geography.a.glaciers.'+slug,topicId:glacierTopic.id,option:'glaciers',title,refs,cards,tasks,practice,check,model,cardViews,minutes:25});
export const glacierLessons=[
make('ice-processes','How moving ice changes the land',['1.11a'],[
 ['Ice is a moving system','Snow that survives successive summers can accumulate and compact into glacier ice. Gravity drives ice downslope through deformation and, where conditions allow, sliding at the bed. Ice can still move forwards when a glacier’s end retreats: retreat describes the changing position of the margin, not ice travelling backwards.'],
 ['Two erosional tools','Debris embedded in moving basal ice can scrape bedrock: abrasion, sometimes leaving grooves or striations. Plucking removes blocks from jointed bedrock when ice–water–rock conditions enable detachment and moving ice carries them away. A water-filled crack alone does not prove that plucking has occurred. Rock structure, debris and basal conditions affect erosion.'],
 ['Carry, then leave','Fallen debris can travel on the ice surface; material can also be enclosed within ice or carried at its base. When debris is released and laid down, deposition occurs. Melting can expose transported sediment but does not turn that sediment into water. The model tracks labelled particles, not a calibrated glacier speed or an exact sediment budget.']
],[['Predict: a rock fragment held at the moving ice base scrapes bedrock. This is…',['Abrasion','Only deposition','Urban runoff'],0],['A jointed block is detached and carried away by ice. This is…',['Plucking','Only weathering in place','A natural levee'],0],['Debris enclosed inside a glacier is transported…',['Within the ice','Only by wind above it','Without any movement'],0],['The glacier end retreats while ice continues downslope. These statements are…',['Compatible: margin position and ice flow differ','Impossible because ice must flow uphill','Proof that debris cannot move'],0]],
[q('ice','p1','Scratches made by debris at an ice–rock contact suggest…',['Abrasion','A new sedimentary rock forming instantly','Floodplain zoning'],0,'Abrasion wears the bed as ice carries tools across it.','abrasion'),q('ice','p2','Which distinguishes plucking from weathering alone?',['Rock is detached and removed by moving ice','All rock simply dissolves in air','Neither involves bedrock'],0,'Breakdown in place differs from removal and transport.','plucking'),q('ice','p3','A boulder emerges as ice melts and remains on the ground. It has been…',['Deposited','Converted entirely into water','Made into an oxbow lake'],0,'The transported material is left behind, not melted into water.','transport-deposition')],
[q('ice','c1','Which process uses debris to scrape bedrock?',['Glacial abrasion','Only root growth','Channel zoning'],0,'Debris carried in basal ice acts as an erosional tool.','abrasion'),q('ice','c2','Removal of a block from fractured bedrock by moving ice is…',['Plucking','Only suspension in a river','Sediment cementation'],0,'Detachment plus removal identifies glacial plucking.','plucking'),q('ice','c3','Which pair gives two valid debris locations during glacial transport?',['On the surface and within the ice','Only in the atmosphere and deep mantle','Only at the sea floor'],0,'Glaciers can carry debris on, within and beneath them.','transport-deposition'),q('ice','c4','A retreating margin necessarily means…',['The ice extent is shrinking there, not that all ice flows uphill','Every ice particle has reversed direction','There is no deposition'],0,'Separate movement of ice from the position of its end.','ice-margin')],'glacier-ice',['flow','abrasion','transport']),
make('upland-slopes','Upland slopes after the ice',['1.11b'],[
 ['Relict does not mean inactive','A relict glaciated upland retains forms made by past ice, but present weathering, gravity and water keep modifying it. Where water enters cracks, repeated freezing and thawing can widen them and help break rock. Water availability and crossing the freezing point matter; a permanently dry or continuously frozen crack is not undergoing repeated freeze–thaw cycles.'],
 ['Slow soil movement','Soil creep is very slow downslope movement under gravity. Expansion and contraction from processes such as wetting/drying or freezing/thawing can help move particles incrementally downslope. Waterlogged material may also move over less permeable or frozen ground. Do not confuse slow soil movement with the sudden release of a rock block.'],
 ['Falls and slides','A rockfall drops or bounces from a steep face; a rockslide moves a mass along a failure surface. Weathering can loosen blocks, while saturation and undercutting may alter stability. Fallen angular debris can accumulate as scree. The animation compresses times: a creep step is not as fast as a rockfall, and not every rain event triggers failure.']
],[['Predict: a wet crack repeatedly freezes and thaws. It may…',['Widen and loosen rock','Automatically become a glacier','Lose the influence of gravity'],0],['Compare slow soil movement with falling blocks. Creep is…',['Gradual downslope movement','A boulder always falling vertically','A coastal transport process only'],0],['A detached block falls from a steep face. This is a…',['Rockfall','Point bar','Natural levee'],0],['A large mass moves along a failure plane. This is a…',['Rockslide','Stationary weathering only','Dissolved load'],0]],
[q('slope','p1','Which conditions support repeated freeze–thaw?',['Water in cracks and repeated freezing/thawing','Dry rock always above freezing','Permanent warmth with no temperature change'],0,'Both moisture and suitable temperature changes matter.','freeze-thaw'),q('slope','p2','Slow incremental soil movement downslope is…',['Soil creep','A waterfall retreat rate by definition','Glacial plucking of every soil grain'],0,'Creep is mass movement under gravity, often extremely slow.','soil-movement'),q('slope','p3','Angular fragments below a rock face may form…',['Scree','A coral reef','A point bar by definition'],0,'Weathering and falling blocks can supply slope debris.','rockfall')],
[q('slope','c1','Relict glaciated landscape means…',['Past ice-shaped forms remain while present processes continue','All landscape change has stopped','Ice must still cover every slope'],0,'Inherited landforms can be actively modified today.','relict'),q('slope','c2','Which is weathering rather than mass movement?',['Rock breaking in place during freeze–thaw','A block falling down a cliff','A soil layer sliding downhill'],0,'Weathering prepares material; gravity-driven transfer moves it.','freeze-thaw'),q('slope','c3','Which identifies a rockslide?',['A mass moving along a slip surface','Only individual blocks in free fall','Only slow chemical dissolution'],0,'Falls and slides have different movement mechanisms.','rockslide'),q('slope','c4','Why is the same animation duration unsuitable as a real speed comparison?',['Soil creep and rockfall operate on very different time scales','All mass movement has identical speed','The replay is a field measurement'],0,'Compressed teaching time is not a measurement of natural rates.','model-time')],'glacier-slopes',['freeze','creep','fall']),
make('climate-weather','Past ice, present weather',['1.11c','Integrated skill 14: conceptual introduction'],[
 ['Past climate leaves a landscape','During colder intervals, persistent snow and a suitable accumulation–loss balance allowed glaciers to develop across parts of the UK uplands. Moving ice eroded and deposited material. Later warming and ice loss exposed inherited landforms. A cold winter today is not equivalent to the long-term conditions that produced a former valley glacier.'],
 ['Seasonal and daily changes','Seasonal means changes through the year; diurnal means changes through a day. Snow cover, frost, rainfall and thaw vary with season, altitude, aspect and local conditions. Suitable wet rock can experience freeze–thaw when temperatures repeatedly cross freezing. The coldest place is not automatically the place with the most cycles.'],
 ['Link weather to a process','Rain can saturate soils and encourage runoff or slope movement; thaw can supply water and release loosened debris. Sun-facing and shaded slopes can behave differently. Our day example, −2°C at night and +3°C in the afternoon, is invented: it illustrates a possible crossing, not a real UK observation, climate average or prediction of rockfall. Real analysis needs dated weather and longer climate records.']
],[['Predict: continuous below-freezing conditions with no thaw. Compared with repeated crossing, this gives…',['Fewer complete freeze–thaw cycles','A new full cycle every minute automatically','Proof of tropical climate'],0],['The change from night to afternoon is…',['Diurnal','Only a century-long climate trend','A glacial moraine'],0],['A change from winter conditions to summer conditions is…',['Seasonal','Only diurnal','A rock family'],0],['Which evidence is needed to investigate current UK weather effects?',['Dated local weather plus process/context evidence','Only this invented temperature pair','Only a distant river’s name'],0]],
[q('climate','p1','Which distinguishes climate from weather?',['Climate concerns longer-term patterns; weather concerns shorter conditions','They both describe only one afternoon','Climate is only a rock type'],0,'Use evidence at the appropriate time scale.','weather-climate'),q('climate','p2','Invented wet-crack example: −2°C night, +3°C afternoon. This can allow…',['Freezing followed by thawing','Proof every block must fall','An observed UK annual mean'],0,'It is a conditional mechanism, not an event prediction.','temperature-cycle'),q('climate','p3','Why can shaded and sunny slopes differ?',['Aspect affects local energy and temperature conditions','Their names change gravity','All slopes receive identical sunlight'],0,'Local conditions modify broad weather patterns.','aspect')],
[q('climate','c1','A former glacial trough in today’s upland is evidence of…',['Inherited ice shaping and subsequent change','A guarantee a glacier occupies it now','No past processes'],0,'Landforms can survive after ice retreats.','past-climate'),q('climate','c2','Diurnal variation refers to…',['Changes during a day','Changes only between geological eras','Only yearly rainfall totals'],0,'Do not confuse daily and seasonal scales.','weather-climate'),q('climate','c3','Why may very cold continuous conditions yield fewer complete freeze–thaw cycles?',['Thawing is needed as well as freezing','Cold removes all water from Earth','Rock becomes immune to every process'],0,'A cycle needs both parts, with water and local conditions.','temperature-cycle'),q('climate','c4','What can the invented temperature pair establish?',['How a possible freezing-point crossing works','Measured weather at a named UK site','A reliable forecast of a particular rockfall'],0,'Illustrative data cannot substitute for observed weather evidence.','weather-evidence')],'glacier-climate',['past','day','rain']),
make('corries-aretes','Corries, tarns and arêtes',['1.12a: corries; glacial lakes/tarns; arêtes','Integrated skill 15: diagram introduction'],[
 ['A hollow becomes a corrie','Snow can accumulate in a sheltered hollow and develop into ice. Weathering supplies debris; plucking and abrasion by moving ice enlarge and deepen the hollow. Rotational ice movement helps excavate a bowl-shaped basin with a steep back wall. The animation is a general mechanism, not the measured history of a particular hollow.'],
 ['Ice leaves, water may remain','After ice loss, water may occupy the over-deepened basin if it is retained behind a rock lip or deposit threshold, forming a tarn or corrie lake. Not every corrie contains water today. A blue lake shape alone does not show its origin: use the surrounding basin, lip, slopes and wider evidence.'],
 ['Two corries, one ridge','Where corries erode back towards one another, the intervening rock ridge can become narrow and sharp: an arête. It is an erosional ridge, not a heap of sediment deposited by ice. Three-dimensional landforms are simplified in our sections; genuine OS contours and field/photo evidence are needed for place-specific recognition.']
],[['Predict: moving ice with basal debris erodes a hollow. It may become…',['Deeper and bowl-shaped','A concrete reservoir by definition','A floodplain levee'],0],['After ice melts, water is retained in an excavated corrie basin. The lake is a…',['Tarn','Spit','Natural levee'],0],['Two corries erode back towards each other. The remaining sharp ridge is an…',['Arête','Oxbow lake','Industrial channel'],0],['A corrie with no lake today is…',['Still possible: water retention varies','Impossible by definition','Proof there was never ice'],0]],
[q('corrie','p1','Which combination helps excavate a corrie?',['Plucking and abrasion by moving ice','Only urban zoning','Deposition of a concrete wall'],0,'Erosion deepens the basin, alongside weathering of the slopes.','corrie'),q('corrie','p2','A tarn occupies…',['A water-retaining glacial basin after ice loss','Every active glacier surface by definition','Only a tidal estuary'],0,'A tarn is a lake, not glacier ice itself.','tarn'),q('corrie','p3','An arête is mainly…',['A narrow erosional ridge','An artificial flood bank','A pile of only deposited sediment'],0,'Back-to-back erosion can sharpen the remaining ridge.','arete')],
[q('corrie','c1','A steep back wall and over-deepened bowl are characteristic of a…',['Corrie','Point bar','Coastal spit'],0,'Connect the form with glacial excavation.','corrie'),q('corrie','c2','Why might a lake remain when corrie ice disappears?',['A basin retains water behind a threshold','All rock automatically becomes impermeable','A lake requires ice still filling it'],0,'Excavation and retention explain the lake; drainage conditions matter.','tarn'),q('corrie','c3','A sharp ridge between neighbouring corries is an…',['Arête','Engineered levee','Oxbow'],0,'It is remaining bedrock shaped by erosion on either side.','arete'),q('corrie','c4','What is needed to recognise an actual mapped corrie confidently?',['Contours, scale and surrounding features on an appropriate map','Only our unscaled blue shape','Only one place name with no evidence'],0,'The schematic introduces form; it is not genuine OS-map evidence.','map-evidence')],'glacier-corrie',['excavate','tarn','arete'])
];
